import React, { useState } from "react";



function FormHandeling() {
  const [formvalue, setFormhandel] = useState({
    id: "",
    name: "",
    email: "",
    password: "",
  });

  const [data, setData] = useState([]);

  const changeHandel = (e) => {
    setFormhandel({
      ...formvalue,
      id: new Date().getTime().toString(),
      [e.target.name]: e.target.value,
    });
  };

  const submitHandel = (e) => {
    e.preventDefault();
    setData([...data, formvalue]);
    setFormhandel({ id: "", name: "", email: "", password: "" });
  };

  const deleteHandel = (id) => {
    const filterdata = data.filter((value) => value.id !== id);
    setData(filterdata);
  };

  return (
    <div className="bg-light min-vh-100 py-5">
      <div className="container">

        {/* 🔷 Form Card */}
        <div className="card shadow-lg p-4 mb-5">
          <h2 className="text-center text-primary mb-4">User Register</h2>

          <form onSubmit={submitHandel}>
            <div className="mb-3">
              <label className="form-label">Name</label>
              <input
                type="text"
                name="name"
                value={formvalue.name}
                onChange={changeHandel}
                className="form-control"
                placeholder="Enter Name"
                required
              />
            </div>

            <div className="mb-3">
              <label className="form-label">Email</label>
              <input
                type="email"
                name="email"
                value={formvalue.email}
                onChange={changeHandel}
                className="form-control"
                placeholder="Enter Email"
                required
              />
            </div>

            <div className="mb-3">
              <label className="form-label">Password</label>
              <input
                type="password"
                name="password"
                value={formvalue.password}
                onChange={changeHandel}
                className="form-control"
                placeholder="Enter Password"
                required
              />
            </div>

            <button className="btn btn-primary w-100">
              Submit 🚀
            </button>
          </form>
        </div>

        {/* 🔷 Table Card */}
        <div className="card shadow-lg p-4">
          <h2 className="text-center text-success mb-4">User Manage</h2>

          <div className="table-responsive">
            <table className="table table-bordered table-hover text-center align-middle">
              <thead className="table-dark">
                <tr>
                  <th>ID</th>
                  <th>Name</th>
                  <th>Email</th>
                  <th>Password</th>
                  <th>Action</th>
                </tr>
              </thead>

              <tbody>
                {data.length > 0 ? (
                  data.map((value) => (
                    <tr key={value.id}>
                      <td>{value.id}</td>
                      <td>{value.name}</td>
                      <td>{value.email}</td>
                      <td>{value.password}</td>
                      <td>
                        <button
                          onClick={() => deleteHandel(value.id)}
                          className="btn btn-danger btn-sm"
                        >
                          Delete ❌
                        </button>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="5" className="text-muted">
                      No Data Found 😔
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>

      </div>
    </div>
  );
}

export default FormHandeling;
